<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Fresh Pantry — Discover Everyday Deliciousness</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
<style>
/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', sans-serif;
  color: #333;
  background: #FEFAE0;
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 { font-family: 'Nunito', sans-serif; font-weight: 800; }

a { color: inherit; text-decoration: none; }

button { cursor: pointer; font-family: 'Nunito', sans-serif; }

img { max-width: 100%; display: block; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* ===== Animations ===== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* ===== Header ===== */
.header {
  background: #fff;
  box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  max-width: 1200px;
  margin: 0 auto;
}

.logo {
  font-family: 'Nunito', sans-serif;
  font-size: 26px;
  font-weight: 900;
  color: #2D6A4F;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: #F4A261;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
}

.header-nav { display: flex; gap: 32px; align-items: center; }

.header-nav a {
  font-family: 'Nunito', sans-serif;
  font-weight: 600;
  font-size: 15px;
  color: #555;
  transition: color 0.2s;
  position: relative;
}

.header-nav a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: #F4A261;
  transition: width 0.25s;
}

.header-nav a:hover { color: #2D6A4F; }
.header-nav a:hover::after { width: 100%; }

.header-cta {
  background: #2D6A4F;
  color: #fff;
  border: none;
  padding: 10px 22px;
  border-radius: 50px;
  font-weight: 700;
  font-size: 14px;
  transition: background 0.2s, transform 0.15s;
}

.header-cta:hover { background: #1b4d37; transform: scale(1.04); }

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 28px;
  color: #2D6A4F;
  padding: 4px;
}

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, #2D6A4F 0%, #1b4d37 40%, #143727 100%);
  color: #fff;
  text-align: center;
  padding: 100px 24px 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(244,162,97,0.15) 0%, transparent 70%);
  border-radius: 50%;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -20%;
  left: -5%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(244,162,97,0.1) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-content { position: relative; z-index: 1; animation: fadeInUp 0.8s ease-out; }

.hero h1 {
  font-size: clamp(36px, 6vw, 60px);
  font-weight: 900;
  line-height: 1.15;
  margin-bottom: 16px;
}

.hero h1 span { color: #F4A261; }

.hero-subtitle {
  font-size: clamp(16px, 2.5vw, 20px);
  opacity: 0.9;
  max-width: 620px;
  margin: 0 auto 36px;
  line-height: 1.6;
}

.hero-ctas { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

.hero-btn {
  padding: 14px 32px;
  border-radius: 50px;
  font-weight: 700;
  font-size: 16px;
  transition: transform 0.2s, box-shadow 0.2s;
  border: none;
}

.hero-btn:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,0,0,0.15); }

.hero-btn-primary {
  background: #F4A261;
  color: #fff;
}

.hero-btn-secondary {
  background: rgba(255,255,255,0.15);
  color: #fff;
  backdrop-filter: blur(10px);
  border: 2px solid rgba(255,255,255,0.25);
}

/* ===== Section Commons ===== */
.section { padding: 80px 24px; }

.section-header {
  text-align: center;
  margin-bottom: 48px;
  animation: fadeInUp 0.6s ease-out;
}

.section-header h2 {
  font-size: clamp(28px, 4vw, 40px);
  color: #2D6A4F;
  margin-bottom: 8px;
}

.section-header p {
  font-size: 17px;
  color: #777;
  max-width: 500px;
  margin: 0 auto;
}

/* ===== Featured Products Carousel ===== */
.featured-section { background: #fff; }

.carousel-wrapper { position: relative; max-width: 1200px; margin: 0 auto; }

.carousel-viewport {
  overflow: hidden;
  border-radius: 16px;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.1, 0.25, 1);
  gap: 20px;
}

.product-card {
  flex: 0 0 calc(25% - 15px);
  min-width: calc(25% - 15px);
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  transition: transform 0.3s, box-shadow 0.3s;
  cursor: pointer;
}

.product-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.1);
}

.product-card-img {
  height: 200px;
  background: linear-gradient(135deg, #e8f5e9, #f0f4c3, #fff3e0);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 56px;
  position: relative;
  overflow: hidden;
}

.product-card-img::after {
  content: '';
  position: absolute;
  bottom: -10px;
  right: -10px;
  width: 60px;
  height: 60px;
  background: rgba(244,162,97,0.15);
  border-radius: 12px;
  transform: rotate(15deg);
}

.product-card-body { padding: 20px; }

.product-card-body h3 {
  font-size: 17px;
  color: #222;
  margin-bottom: 4px;
  font-weight: 700;
}

.product-card-body .product-desc {
  font-size: 13px;
  color: #888;
  margin-bottom: 10px;
  line-height: 1.4;
}

.product-price {
  font-family: 'Nunito', sans-serif;
  font-size: 20px;
  font-weight: 800;
  color: #2D6A4F;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: none;
  background: #fff;
  box-shadow: 0 4px 16px rgba(0,0,0,0.12);
  font-size: 22px;
  color: #2D6A4F;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: transform 0.2s, box-shadow 0.2s;
}

.carousel-btn:hover { transform: translateY(-50%) scale(1.08); box-shadow: 0 6px 20px rgba(0,0,0,0.18); }

.carousel-btn:active { transform: translateY(-50%) scale(0.95); }

.carousel-btn-left { left: -20px; }
.carousel-btn-right { right: -20px; }

.carousel-btn:disabled { opacity: 0.4; cursor: not-allowed; }

/* ===== Seasonal Picks ===== */
.seasonal-section { background: #faf8f0; }

.seasonal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
  max-width: 1200px;
  margin: 0 auto;
}

.seasonal-card {
  background: #fff;
  border-radius: 16px;
  padding: 28px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.05);
  transition: transform 0.3s, box-shadow 0.3s;
  display: flex;
  gap: 20px;
  align-items: flex-start;
}

.seasonal-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.1);
}

.seasonal-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: linear-gradient(135deg, #F4A261, #e08f4a);
  color: #fff;
  font-size: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.seasonal-info h3 {
  font-size: 17px;
  color: #222;
  margin-bottom: 4px;
  font-weight: 700;
}

.seasonal-info .seasonal-desc {
  font-size: 13px;
  color: #888;
  margin-bottom: 8px;
  line-height: 1.4;
}

.seasonal-info .seasonal-price {
  font-family: 'Nunito', sans-serif;
  font-size: 18px;
  font-weight: 800;
  color: #F4A261;
}

/* ===== Categories ===== */
.categories-section { background: #fff; }

.categories-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 24px;
  max-width: 1200px;
  margin: 0 auto;
}

.category-card {
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  aspect-ratio: 1;
  cursor: pointer;
  box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  transition: transform 0.35s cubic-bezier(0.25, 0.1, 0.25, 1), box-shadow 0.35s;
}

.category-card:hover {
  transform: scale(1.06);
  box-shadow: 0 12px 32px rgba(0,0,0,0.15);
}

.category-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
}

.category-card:nth-child(1) .category-bg { background: linear-gradient(135deg, #fff3e0, #ffe0b2); }
.category-card:nth-child(2) .category-bg { background: linear-gradient(135deg, #e8f5e9, #c8e6c9); }
.category-card:nth-child(3) .category-bg { background: linear-gradient(135deg, #e3f2fd, #bbdefb); }
.category-card:nth-child(4) .category-bg { background: linear-gradient(135deg, #fce4ec, #f8bbd0); }
.category-card:nth-child(5) .category-bg { background: linear-gradient(135deg, #f3e5f5, #e1bee7); }

.category-overlay {
  position: absolute;
  inset: 0;
  background: rgba(45, 106, 79, 0.82);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.35s;
  color: #fff;
  gap: 8px;
}

.category-card:hover .category-overlay { opacity: 1; }

.category-overlay h3 {
  font-size: 22px;
  font-weight: 800;
}

.category-overlay span {
  font-size: 13px;
  opacity: 0.9;
  text-align: center;
  padding: 0 16px;
}

/* ===== Brand Highlights ===== */
.highlights-section {
  background: #2D6A4F;
  color: #fff;
  padding: 64px 24px;
}

.highlights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 32px;
  max-width: 1200px;
  margin: 0 auto;
}

.highlight-item {
  text-align: center;
  animation: fadeInUp 0.6s ease-out;
}

.highlight-number {
  font-family: 'Nunito', sans-serif;
  font-size: clamp(36px, 5vw, 52px);
  font-weight: 900;
  color: #F4A261;
  line-height: 1;
  margin-bottom: 8px;
}

.highlight-label {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 6px;
}

.highlight-desc {
  font-size: 14px;
  opacity: 0.75;
  line-height: 1.5;
}

/* ===== Store Locator ===== */
.locator-section { background: #faf8f0; }

.locator-box {
  max-width: 580px;
  margin: 0 auto;
}

.locator-form {
  display: flex;
  gap: 10px;
  margin-bottom: 32px;
}

.locator-input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid #e0dcd0;
  border-radius: 50px;
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  outline: none;
  transition: border-color 0.2s;
}

.locator-input:focus { border-color: #2D6A4F; }

.locator-search-btn {
  background: #2D6A4F;
  color: #fff;
  border: none;
  padding: 14px 28px;
  border-radius: 50px;
  font-weight: 700;
  font-size: 15px;
  transition: background 0.2s;
}

.locator-search-btn:hover { background: #1b4d37; }

.locator-results { display: none; }

.locator-results.visible {
  display: flex;
  flex-direction: column;
  gap: 16px;
  animation: fadeIn 0.4s ease-out;
}

.store-card {
  background: #fff;
  border-radius: 14px;
  padding: 22px 24px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.05);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.store-card h4 {
  font-size: 17px;
  color: #222;
  margin-bottom: 2px;
}

.store-card .store-address {
  font-size: 13px;
  color: #888;
}

.store-card .store-hours {
  font-size: 13px;
  color: #666;
  display: flex;
  align-items: center;
  gap: 4px;
}

.store-distance {
  background: #e8f5e9;
  color: #2D6A4F;
  font-weight: 700;
  font-size: 14px;
  padding: 8px 16px;
  border-radius: 50px;
}

/* ===== Newsletter ===== */
.newsletter-section { background: #fff; }

.newsletter-box {
  max-width: 550px;
  margin: 0 auto;
  text-align: center;
}

.newsletter-form {
  display: flex;
  gap: 10px;
  margin-top: 24px;
}

.newsletter-input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid #e0dcd0;
  border-radius: 50px;
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  outline: none;
  transition: border-color 0.2s;
}

.newsletter-input:focus { border-color: #2D6A4F; }

.newsletter-btn {
  background: #F4A261;
  color: #fff;
  border: none;
  padding: 14px 28px;
  border-radius: 50px;
  font-weight: 700;
  font-size: 15px;
  transition: background 0.2s;
}

.newsletter-btn:hover { background: #e08f4a; }

.newsletter-confirmation {
  display: none;
  margin-top: 16px;
  padding: 14px 20px;
  background: #e8f5e9;
  color: #2D6A4F;
  border-radius: 12px;
  font-weight: 600;
  font-size: 15px;
}

.newsletter-confirmation.visible { display: block; animation: fadeIn 0.4s ease-out; }

/* ===== Footer ===== */
.footer {
  background: #1b4d37;
  color: #fff;
  padding: 64px 24px 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 40px;
  max-width: 1200px;
  margin: 0 auto 48px;
}

.footer-col h4 {
  font-size: 16px;
  font-weight: 800;
  margin-bottom: 16px;
  color: #F4A261;
}

.footer-col a {
  display: block;
  font-size: 14px;
  opacity: 0.75;
  margin-bottom: 10px;
  transition: opacity 0.2s;
}

.footer-col a:hover { opacity: 1; }

.footer-bottom {
  text-align: center;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.12);
  font-size: 14px;
  opacity: 0.6;
}

.footer-brand {
  text-align: center;
  margin-bottom: 32px;
}

.footer-brand span {
  font-family: 'Nunito', sans-serif;
  font-size: 24px;
  font-weight: 900;
  color: #F4A261;
}

/* ===== Responsive ===== */
@media (max-width: 900px) {
  .product-card { flex: 0 0 calc(50% - 10px); min-width: calc(50% - 10px); }

  .carousel-btn-left { left: -8px; }
  .carousel-btn-right { right: -8px; }
  .carousel-btn { width: 40px; height: 40px; font-size: 18px; }

  .hero { padding: 60px 24px 50px; }
  .section { padding: 50px 24px; }
}

@media (max-width: 640px) {
  .product-card { flex: 0 0 85%; min-width: 85%; }

  .header-nav { display: none; }
  .header-cta { display: none; }
  .mobile-menu-btn { display: block; }

  .hero-ctas { flex-direction: column; align-items: center; }

  .newsletter-form { flex-direction: column; }
  .locator-form { flex-direction: column; }

  .seasonal-card { flex-direction: column; align-items: flex-start; }

  .carousel-btn-left { left: 0; }
  .carousel-btn-right { right: 0; }

  .store-card { flex-direction: column; align-items: flex-start; }
}

/* ===== Mobile Menu Overlay ===== */
.mobile-menu {
  display: none;
  position: fixed;
  inset: 0;
  background: #FEFAE0;
  z-index: 200;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 28px;
}

.mobile-menu.open { display: flex; }

.mobile-menu a {
  font-family: 'Nunito', sans-serif;
  font-size: 22px;
  font-weight: 700;
  color: #2D6A4F;
}

.mobile-menu-close {
  position: absolute;
  top: 20px;
  right: 24px;
  background: none;
  border: none;
  font-size: 32px;
  color: #2D6A4F;
}
</style>
</head>
