<script>
let carouselIndex = 0;

function getCarouselState() {
  const track = document.getElementById('carouselTrack');
  const cards = track.children;
  const viewport = track.parentElement;
  const cardWidth = cards[0].offsetWidth;
  const gap = 20;
  const slideWidth = cardWidth + gap;
  const visibleCards = Math.floor(viewport.offsetWidth / slideWidth) || 1;
  const maxIndex = Math.max(0, cards.length - visibleCards);
  return { track, cards, slideWidth, visibleCards, maxIndex };
}

function slideCarousel(direction) {
  const { track, slideWidth, maxIndex } = getCarouselState();
  carouselIndex = Math.max(0, Math.min(carouselIndex + direction, maxIndex));
  track.style.transform = `translateX(-${carouselIndex * slideWidth}px)`;
  updateCarouselButtons();
}

function updateCarouselButtons() {
  const { maxIndex } = getCarouselState();
  document.getElementById('carouselLeft').disabled = carouselIndex === 0;
  document.getElementById('carouselRight').disabled = carouselIndex >= maxIndex;
}

let resizeTimeout;
window.addEventListener('resize', () => {
  clearTimeout(resizeTimeout);
  resizeTimeout = setTimeout(() => {
    const { maxIndex } = getCarouselState();
    if (carouselIndex > maxIndex) carouselIndex = maxIndex;
    slideCarousel(0);
  }, 100);
});

function toggleMobileMenu() {
  document.getElementById('mobileMenu').classList.toggle('open');
}

function searchStores() {
  const input = document.getElementById('zipInput');
  const results = document.getElementById('locatorResults');

  if (input.value.trim().length >= 5) {
    results.classList.add('visible');
    results.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  } else {
    input.classList.add('locator-input-error');
    input.style.borderColor = '#e74c3c';
    setTimeout(() => {
      input.style.borderColor = '#e0dcd0';
      input.classList.remove('locator-input-error');
    }, 1500);
  }
}

function subscribeNewsletter() {
  const input = document.getElementById('emailInput');
  const confirmation = document.getElementById('newsletterConfirmation');

  if (input.value.trim() && input.value.includes('@')) {
    confirmation.classList.add('visible');
    input.value = '';
    setTimeout(() => confirmation.classList.remove('visible'), 5000);
  } else {
    input.style.borderColor = '#e74c3c';
    input.placeholder = 'Please enter a valid email address';
    setTimeout(() => {
      input.style.borderColor = '#e0dcd0';
      input.placeholder = 'Your email address';
    }, 2000);
  }
}

document.getElementById('zipInput').addEventListener('keydown', function(e) {
  if (e.key === 'Enter') searchStores();
});

document.getElementById('emailInput').addEventListener('keydown', function(e) {
  if (e.key === 'Enter') subscribeNewsletter();
});

// Initialize carousel button state
updateCarouselButtons();
</script>

